Function to convert surrogate pair to html code

{noformat}var surrogateStringToHtml = function(surrogateStr) {
    // Extraer los números de los códigos HTML
    const matches = surrogateStr.match(/&#(\d+);/g);
    if (!matches || matches.length !== 2) {
        throw new Error("Debe contener exactamente dos códigos HTML de surrogate pair");
    }

    const high = parseInt(matches[0].replace(/&#|;/g, ''), 10);
    const low  = parseInt(matches[1].replace(/&#|;/g, ''), 10);

    // Calcular el code point real
    const codePoint = ((high - 0xD800) << 10) + (low - 0xDC00) + 0x10000;

    // Devolver como código HTML decimal
    return `&#${codePoint};`;
}
